# Output guardrail: validate the model's JSON with Pydantic, re-prompt once with the error.
from typing import Literal
from pydantic import BaseModel, Field, ValidationError

class SqlAnswer(BaseModel):
    status: Literal["ok", "refuse", "clarify"]
    sql: str | None = Field(default=None, max_length=4000)
    explanation: str = Field(max_length=500)

def generate_sql(call_model, messages, retries: int = 1) -> SqlAnswer:
    for attempt in range(retries + 1):
        raw = call_model(messages)
        try:
            return SqlAnswer.model_validate_json(raw)
        except ValidationError as e:
            messages = messages + [
                {"role": "assistant", "content": raw},
                {"role": "user", "content": f"Invalid JSON for schema: {e.errors()[:3]}. Return only valid JSON."},
            ]
    return SqlAnswer(status="refuse", explanation="Could not produce a valid query.")
