# Action guardrail: EXPLAIN cost check before running model SQL (psycopg2).
import json

def safe_run(conn, sql: str, max_cost: float = 50_000.0):
    with conn.cursor() as cur:
        try:
            cur.execute("SET LOCAL ROLE llm_reader")
            cur.execute("SET LOCAL statement_timeout = '5s'")
            cur.execute("EXPLAIN (FORMAT JSON) " + sql)       # sql already passed allow-list checks
            plan = cur.fetchone()[0][0]["Plan"]
            if plan["Total Cost"] > max_cost:
                return {"error": f"query too expensive (cost {plan['Total Cost']:.0f})"}
            cur.execute(f"SELECT * FROM ({sql}) q LIMIT 200")
            return {"rows": cur.fetchall()}
        finally:
            conn.rollback()
