import re

FORBIDDEN = re.compile(r"\b(insert|update|delete|drop|alter|grant|truncate)\b", re.I)

def check(sql):
    s = sql.strip().rstrip(";")
    if ";" in s:
        return "reject: multiple statements"
    if not re.match(r"(select|with)\b", s, re.I):
        return "reject: not a query"
    if FORBIDDEN.search(s):
        return "reject: write keyword"
    if not re.search(r"\blimit\s+\d+\s*$", s, re.I):
        s += " LIMIT 100"
    return s

for q in ["SELECT id FROM orders;", "select 1; drop table x",
          "WITH t AS (DELETE FROM a RETURNING *) SELECT * FROM t",
          "select * from sales limit 5"]:
    print(check(q))

